A=[[2,2,2,2],[2,0,0,0],[2,0,0,2],[2,0,2,2]]
positions=[(r,c) for r in range(4) for c in range(4) if A[r][c]==2]
out=[[0]*19 for _ in range(19)]
for R,C in positions:
    for i in range(4):
        for j in range(4):
            out[5*R+i][5*C+j]=A[i][j]
    out[5*R+R][5*C+C]=8
print(positions)
print('\n'.join(' '.join(map(str,row)) for row in out))

